(()=>{'use strict';
if(window.__erpHoverTips)return;window.__erpHoverTips=true;
const tip=document.createElement('div');tip.id='erp-hover-tooltip';tip.setAttribute('role','tooltip');tip.setAttribute('popover','manual');tip.hidden=true;document.body.append(tip);
let active=null,timer=0,original='',described=false;
function hide(){clearTimeout(timer);if(active){if(active.getAttribute('title')==='')active.setAttribute('title',original);if(described){const ids=(active.getAttribute('aria-describedby')||'').split(/\s+/).filter(x=>x&&x!==tip.id);if(ids.length)active.setAttribute('aria-describedby',ids.join(' '));else active.removeAttribute('aria-describedby')}}if(tip.matches(':popover-open'))tip.hidePopover();tip.hidden=true;active=null;described=false}
function show(){if(!active?.isConnected)return hide();tip.textContent=original;tip.hidden=false;if(tip.showPopover)tip.showPopover();const a=active.getBoundingClientRect(),b=tip.getBoundingClientRect();tip.style.left=Math.max(16,Math.min(innerWidth-b.width-16,a.left+(a.width-b.width)/2))+'px';const top=a.top-b.height-8;tip.style.top=Math.max(8,Math.min(innerHeight-b.height-8,top>=8?top:a.bottom+8))+'px';const ids=(active.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean);if(!ids.includes(tip.id)){active.setAttribute('aria-describedby',[...ids,tip.id].join(' '));described=true}}
function enter(e){const el=e.target instanceof Element?e.target.closest('[title]'):null;if(!el||el===active)return;if(e.type==='pointerover'&&el.contains(e.relatedTarget))return;hide();const title=el.getAttribute('title');if(!title?.trim())return;active=el;original=title;el.setAttribute('title','');timer=setTimeout(show,e.type==='focusin'?0:240)}
function leave(e){if(active&&active.contains(e.target)&&!active.contains(e.relatedTarget))hide()}
document.addEventListener('pointerover',enter);document.addEventListener('focusin',enter);document.addEventListener('pointerout',leave);document.addEventListener('focusout',leave);document.addEventListener('pointerdown',hide);document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});document.addEventListener('scroll',hide,true);window.addEventListener('resize',hide);
})();
